import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Resolves the effective registration date to a business day: a supplied date is used as-is,
 * a missing one defaults to the server's current date, and either way a Saturday, Sunday or
 * listed public holiday is rolled forward to the next non-holiday business day. Kept as one
 * tiny, self-contained unit so every rule that depends on the registration date shares the
 * same adjustment without growing a handler.
 */
final class RegistrationBusinessDay {

    private static final Set<LocalDate> HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    private RegistrationBusinessDay() {
    }

    static LocalDate effective(LocalDate supplied) {
        LocalDate date = supplied == null ? LocalDate.now() : supplied;
        while (isNonBusinessDay(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isNonBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY || HOLIDAYS.contains(date);
    }
}

